var pact = Pact.V4("Something API Consumer", "Something API", new PactConfig());
IPactBuilderV4 builder = pact.WithHttpInteractions();

builder.UponReceiving("A GET request to retrieve the something")
    .Given("There is a something with id 'tester'")
    .WithRequest(HttpMethod.Get, "/somethings/tester")
.WillRespond().WithStatus(HttpStatusCode.OK).WithJsonBody(new { id = "tester" });

await builder.VerifyAsync(async ctx => {
    var client = new SomethingApiClient(ctx.MockServerUri);      // code under test
    Assert.Equal("tester", (await client.GetSomething("tester")).Id);
});
